import json,sys
d=open('prices.db','rb').read()
def varint(b,i):
    v=0
    for k in range(9):
        c=b[i+k]
        if k==8: return (v<<8)|c,i+9
        v=(v<<7)|(c&0x7f)
        if c<0x80: return v,i+k+1
n=int.from_bytes(d[3:5],'big');rows=[]
for j in range(n):
    p=int.from_bytes(d[8+2*j:10+2*j],'big')
    ln,i=varint(d,p);rid,i=varint(d,i);h0=i;hl,i=varint(d,i);ts=[]
    while i<h0+hl: t,i=varint(d,i);ts.append(t)
    vals=[];q=h0+hl
    for t in ts:
        if t==0: vals.append(None)
        elif 1<=t<=6: s=[0,1,2,3,4,6,8][t];vals.append(int.from_bytes(d[q:q+s],'big',signed=True));q+=s
        elif t==7: import struct;vals.append(struct.unpack('>d',d[q:q+8])[0]);q+=8
        elif t in(8,9): vals.append(t-8)
        elif t>=13 and t%2: s=(t-13)//2;vals.append(d[q:q+s].decode());q+=s
    print(rid,vals);rows.append((rid,vals))
rows.sort()
json.dump([{"item":v[-2],"price":v[-1]} for r,v in rows],open('recovered.json','w'),ensure_ascii=False,indent=1)
